#include <bits/stdc++.h>using namespace std;#define int long long#define double long long int32_t main() {    int n; // number of nodes;    cin >> n;    vector<pair<int, int>> adj[n + 1];    for (int i = 0; i < n; i++) {        int a, b, w;        cin >> a >> b >> w;        adj[a].push_back({b, w});        adj[b].push_back({a, w});    }    int answer = 0;    vector<int> cost(n + 1, 0);    vector<bool> visited(n + 1, false);    queue<int> q;    int source = 0;    q.push(source);    visited[source] = true;    while (!q.empty()) {        int node = q.front();        q.pop();        for (auto edge : adj[node]) {            int neighbor = edge.first;            int price = edge.second;            if (!visited[neighbor]) {                visited[neighbor] = true;                cost[neighbor] = cost[node] + price;                answer = max(answer, cost[neighbor]);                q.push(neighbor);            }        }    }    cout << answer << "\n";}